def transform(grid):
    from collections import Counter
    flat = Counter(v for row in grid for v in row)
    accent = min(flat, key=flat.get)
    out = []
    for row in grid:
        if accent in row:
            out.append([1 if v != accent else v for v in row])
        else:
            out.append(list(row))
    return out
